568	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
569	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
570		type pending struct {
571			id  seriesID
572			ref SeriesRef
573			ts  int64
574			val float64
575		}
576	
577		added := 0
578		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
579		seen := make(map[seriesID]map[int64]float64)
580		// 仅记录需要落盘的新增点；校验全部通过后才提交。
581		commits := make([]pending, 0, len(items))
582	
583		failAt := func(index int, msg string) *LineError {
584			return &LineError{Status: "error", Index: index, Error: msg}
585		}
586		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
587			return &LineError{
588				Status: "error",
589				Index:  index,
590				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
591					ref, ts, formatFloat(existing), formatFloat(submitted)),
592				Conflict: &Conflict{
593					// 标签必须复制：冲突结果是本次失败的独立记录，
594					// 调用方修改它不能改动已存序列的身份。
595					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
596					Timestamp: ts,
597					Existing:  existing,
598					Submitted: submitted,
599				},
600			}
601		}
602	
603		for i, item := range items {
604			pos := i + 1
605			p, err := parseSample(item)
606			if err != nil {
607				return nil, failAt(pos, err.Error())
608			}
609	
610			id := makeSeriesID(p.name, p.labels)
611			ref := SeriesRef{Name: p.name, Labels: p.labels}
612	
613			// 同一采样位置无论值来自本批较早接受的点还是此前批次已写入的点，
614			// 都走同一条判定：转换后的 float64 相等即重复、成功忽略，不同即冲突、
615			// 整批拒绝。existing 是该位置当前生效的值，两种来源下语义一致。
616			if existing, ok := s.positionValue(seen, id, p.ts); ok {
617				if existing != p.value {
618					return nil, conflictAt(pos, ref, p.ts, existing, p.value)
619				}
620				// 等值重复：成功忽略。seen 记录的是生效值 existing 而不是本次
621				// 提交的 p.value：数值相等但表示不同（如已存 -0、本次提交 +0）时，
622				// 本批后续在同位置的冲突必须如实报告最先接受的值，
623				// 不能被这条被忽略的重复改写。
624				if seen[id] == nil {
625					seen[id] = map[int64]float64{}
626				}
627				seen[id][p.ts] = existing
628				continue
629			}
630	
631			added++
632			if seen[id] == nil {
633				seen[id] = map[int64]float64{}
634			}
635			seen[id][p.ts] = p.value
636			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
637		}
638	
639		// 全部采样点合法且无冲突，原子提交本批新增点。
640		for _, c := range commits {
641			sr := s.series[c.id]
642			if sr == nil {
643				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
644				s.series[c.id] = sr
645			}
646			sr.points[c.ts] = c.val
647		}
648	
649		return s.snapshot(added, len(items)-added), nil
650	}
651	
652	// positionValue 解析一个采样位置（序列身份 + 时间戳）当前生效的值：
653	// 本批已接受的值优先（含与已写入数据等值而被忽略的重复所登记的生效值），
654	// 其次是此前批次已成功写入的值；该位置没有任何数据时 ok 为 false。
655	// 重复与冲突判定只看这里返回的值，不再区分两种来源。
656	func (s *MetricStore) positionValue(seen map[seriesID]map[int64]float64, id seriesID, ts int64) (value float64, ok bool) {
657		if byTS, found := seen[id]; found {
658			if v, hit := byTS[ts]; hit {
659				return v, true
660			}
661		}
662		if sr, found := s.series[id]; found {
663			if v, hit := sr.points[ts]; hit {
664				return v, true
665			}
666		}
667		return 0, false
668	}
669	
670	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
671	func formatFloat(v float64) string {
672		return strconv.FormatFloat(v, 'g', -1, 64)
673	}
674	
675	type parsedQuery struct {
676		name   string
677		start  int64
678		end    int64
679		labels map[string]string
680	}
681	
682	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
683	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
684		q, err := parseQuery(raw)
685		if err != nil {
686			return nil, &LineError{Status: "error", Error: err.Error()}
687		}
688		if q.start > q.end {
689			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
690				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
691		}
692		return s.runQuery(q), nil
693	}
694	
695	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
696	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
697	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
698		var q parsedQuery
699		err := parseStrictObject(raw,
700			"each query must be a JSON object",
701			"unexpected content after the query object",
702			[]string{"op", "name", "start", "end"},
703			map[string]fieldReader{
704				"op": func(dec *json.Decoder) error {
705					t, err := dec.Token()
706					if err != nil {
707						return err
708					}
709					op, ok := t.(string)
710					if !ok {
711						return fmt.Errorf(`field "op" must be a string`)
712					}
713					if op != "query" {
714						return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
715					}
716					return nil
717				},
718				"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
719				"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
720				"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
721				"labels": func(dec *json.Decoder) error {
722					return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
723				},
724			})
725		return q, err
726	}
727	
728	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
729	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
730	func labelsMatch(want, stored map[string]string) bool {
731		for k, v := range want {
732			got, ok := stored[k]
733			if !ok || got != v {
734				return false
735			}
736		}
737		return true
738	}
739	
740	// runQuery 只读统计已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
741	// 序列身份的整理（标签副本、排序键值对、排列次序）与写入快照共用同一套
742	// organizeSeries 规则，只是入选范围不同：这里先按名称与标签条件筛出命中序列
743	// 再整理，不为无关指标承担展示准备；筛后剩余序列的相对次序因此与写入全量
744	// 结果一致。查询只返回每条序列的点数与均值，不把区间内采样点按时间排成完整
745	// Point 列表——单次遍历点表只做计数与精确有理数求和（计数与均值都与点的
746	// 排列次序无关）。区间内没有点的序列不列出，不补零值条目。
747	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
748		matched := make([]*storedSeries, 0)
749		for _, sr := range s.series {
750			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
751				continue
752			}
753			matched = append(matched, sr)
754		}
755		organized := organizeSeries(matched)
756	
757		out := make([]QuerySeries, 0, len(organized))
758		for _, entry := range organized {
759			// 一次遍历直接统计：区间内点的个数与精确总和。不构造值切片、
760			// 不排序时间戳，避免为只返回 count/average 的查询承担采样明细展示。
761			// 求和在有理数上精确完成：与写入顺序、批次划分无关，正负大数抵消后的
762			// 小余量不会丢失，总和超出 float64 范围时均值仍然有限。
763			count := 0
764			sum := new(big.Rat)
765			r := new(big.Rat)
766			for ts, v := range entry.sr.points {
767				if ts < q.start || ts > q.end {
768					continue
769				}
770				count++
771				// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
772				sum.Add(sum, r.SetFloat64(v))
773			}
774			if count == 0 {
775				continue
776			}
777			sum.Quo(sum, r.SetInt64(int64(count)))
778			out = append(out, QuerySeries{
779				Name:   entry.ref.Name,
780				Labels: entry.ref.Labels,
781				Count:  count,
782				// 精确平均舍入到最近可表示 float64（正中取偶）；精确为零时返回 +0。
783				Average: ratToFloat64NearestEven(sum),
784			})
785		}
786		return &QueryResult{Status: "ok", Op: "query", Series: out}
787	}
788	
789	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
790	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
791	func ratToFloat64NearestEven(x *big.Rat) float64 {
792		if x.Sign() == 0 {
793			return 0
794		}
795		num := new(big.Int).Set(x.Num())
796		den := x.Denom()
797		neg := num.Sign() < 0
798		if neg {
799			num.Neg(num)
800		}
801	
802		// e 满足 2^e <= num/den < 2^(e+1)。
803		e := floorLog2Rat(num, den)
804		var m *big.Int
805		scale := 0
806		if e >= -1022 {
807			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
808			scale = e - 52
809			m = roundScaledRatio(num, den, scale)
810			if m.BitLen() == 54 {
811				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
812				m.Rsh(m, 1)
813				scale++
814			}
815		} else {
816			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
817			scale = -1074
818			m = roundScaledRatio(num, den, scale)
819		}
820		// m < 2^53，可以精确放入 int64 与 float64。
821		f := math.Ldexp(float64(m.Int64()), scale)
822		if neg {
823			return -f
824		}
825		return f
826	}
827	
828	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
829	func floorLog2Rat(num, den *big.Int) int {
830		k := num.BitLen() - den.BitLen()
831		var t big.Int
832		if k >= 0 {
833			t.Lsh(den, uint(k))
834			if num.Cmp(&t) >= 0 {
835				return k
836			}
837			return k - 1
838		}
839		t.Lsh(num, uint(-k))
840		if t.Cmp(den) >= 0 {
841			return k
842		}
843		return k - 1
844	}
845	
846	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
847	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
848		n := new(big.Int).Set(num)
849		d := new(big.Int).Set(den)
850		if scale >= 0 {
851			d.Lsh(d, uint(scale))
852		} else {
853			n.Lsh(n, uint(-scale))
854		}
855		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
856		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
857		case 1:
858			q.Add(q, big.NewInt(1))
859		case 0:
860			if q.Bit(0) == 1 {
861				q.Add(q, big.NewInt(1))
862			}
863		}
864		return q
865	}
866	
867	// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
868	// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
869	// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
870	// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
871	// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
872	// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
873	// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
874	// 与标签书写顺序、字符是否以 JSON 转义书写无关。
875	func (r SeriesRef) String() string {
876		var b strings.Builder
877		b.WriteString(identityText(r.Name))
878		b.WriteByte('{')
879		for i, p := range sortedPairs(r.Labels) {
880			if i > 0 {
881				b.WriteByte(',')
882			}
883			b.WriteString(identityText(p.Key))
884			b.WriteByte('=')
885			b.WriteString(identityText(p.Value))
886		}
887		b.WriteByte('}')
888		return b.String()
889	}
890	
891	// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
892	// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
893	// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
894	// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
895	// 因此渲染结果不会把内容字符误读为标签边界。
896	func identityText(s string) string {
897		if s == "" || s != strings.TrimSpace(s) {
898			return strconv.Quote(s)
899		}
900		for _, r := range s {
901			if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
902				return strconv.Quote(s)
903			}
904		}
905		return s
906	}
907	
908	// organizedSeries 是结果整理中的一条序列：携带已存序列指针、
909	// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
910	// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
911	// 整理好的键值对，供排序比较直接复用。写入快照与区间查询都经由
912	// organizeSeries 得到这样的条目，区别只在入选的序列范围。
913	type organizedSeries struct {
914		sr    *storedSeries
915		ref   SeriesRef
916		pairs []labelPair
917	}
918	
919	// seriesLess 是写入快照与区间查询共用的序列次序约定：先按指标名字符串
920	// 字典序，同名再按标签键升序后的键值对逐对比较（先比键再比值，前一对
921	// 相同才比下一对；较短集合是完整前缀时排前，无标签序列因此排在最前）。
922	// 标签值按字符串比较（"10" 在 "2" 之前）。排序只看解析后的真实身份，
923	// 与冲突原因里的展示文字、标签的输入次序无关。
924	func seriesLess(a, b organizedSeries) bool {
925		if a.ref.Name != b.ref.Name {
926			return a.ref.Name < b.ref.Name
927		}
928		return compareLabelPairs(a.pairs, b.pairs) < 0
929	}
930	
931	// organizeSeries 是两种成功结果共用的序列身份整理：对入选的每条已存序列
932	// 复制独立的标签副本、预整理按键升序的键值对，并按 seriesLess 的统一次序
933	// 排列。入选范围由调用方决定：写入快照传入全部已提交序列，区间查询只传入
934	// 名称与标签条件命中的序列；两者因此遵循同一套整理规则而各自保留数据范围。
935	// 每条序列的标签只在入选时整理一次：排序后的键值对随条目保留，sort 的反复
936	// 比较直接复用同一份结果，不会因一条序列参与多次比较而反复整理同一套标签。
937	// 整理结果不复制采样点；写入快照的采样点选取与升序排列由 allSeriesPoints
938	// 完成，区间查询只在点表上计数与求和。
939	func organizeSeries(selected []*storedSeries) []organizedSeries {
940		out := make([]organizedSeries, 0, len(selected))
941		for _, sr := range selected {
942			// 标签必须复制：成功结果是当次操作的独立记录，
943			// 调用方修改结果标签不能改动已存序列的身份。
944			labels := cloneLabels(sr.ref.Labels)
945			out = append(out, organizedSeries{
946				sr:    sr,
947				ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
948				pairs: sortedPairs(labels),
949			})
950		}
951		sort.Slice(out, func(i, j int) bool { return seriesLess(out[i], out[j]) })
952		return out
953	}
954	
955	// allSeriesPoints 按 timestamp 升序返回一条已存序列的全部采样点，数值与
956	// 时间戳一一对应，供写入快照展示。返回的是新建切片与新建 Point，调用方对
957	// 采样点的修改不影响存储，也不影响此前或此后取得的其他成功结果。区间查询
958	// 不构造这样的明细列表，只在点表上计数与求和。
959	func allSeriesPoints(sr *storedSeries) []Point {
960		tsList := make([]int64, 0, len(sr.points))
961		for ts := range sr.points {
962			tsList = append(tsList, ts)
963		}
964		sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
965		points := make([]Point, len(tsList))
966		for i, ts := range tsList {
967			points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
968		}
969		return points
970	}
971	
972	// snapshot 生成按规范排序的全部序列视图：入选范围是全部已提交序列，
973	// 身份整理与次序来自 organizeSeries，点排列来自 allSeriesPoints；
974	// 区间查询共用同一套身份整理，但只对命中序列统计点数与精确均值。
975	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
976		all := make([]*storedSeries, 0, len(s.series))
977		for _, sr := range s.series {
978			all = append(all, sr)
979		}
980		organized := organizeSeries(all)
981		views := make([]SeriesView, 0, len(organized))
982		for _, os := range organized {
983			views = append(views, SeriesView{
984				Name:   os.ref.Name,
985				Labels: os.ref.Labels,
986				Points: allSeriesPoints(os.sr),
987			})
988		}
989		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
990	}
991

