11	// 本文件只针对统一逐行入口 MetricStore.ProcessLine 的公开返回约定做回归保障：
12	// 写入数组与查询对象在同一份内存数据上交替进入同一个入口，调用方只看返回的
13	// result 是否为 nil 就能判定成功与否，无须先识别它是写入结果还是查询结果。
14	//
15	// 约定必须保持：
16	//
17	//   - 任何失败（数值冲突、采样点字段校验、查询字段校验、倒置区间、整行解析
18	//     失败、顶层值不是数组或对象）都返回真正的 nil 接口结果与非空的 *LineError；
19	//     不能把带类型的 nil 指针（如 (*BatchResult)(nil)）装进 any，否则调用方的
20	//     result == nil 会把失败误判为成功。
21	//   - 成功（含空写入批次与无命中查询）返回非 nil 的具体结果（*BatchResult 或
22	//     *QueryResult）且错误为 nil；空结果不是失败。
23	//   - 失败的结构化原因按类别携带位置：冲突带 index 与 conflict；采样点字段
24	//     校验带 index 但不带 conflict；查询失败与整行失败两者都不带。
25	//   - 失败不改变已存数据：冲突/字段校验拒绝整批（批内前面的合法新增点也不
26	//     提交），失败查询与整行解析失败后，合法查询仍能看到此前提交的采样点。
27	//
28	// 专用入口 IngestLine/QueryLine 与命令行行为由其他测试保障，这里不重复。
29	
30	// callerResultFailed 模拟真实调用方对统一入口的使用方式：成功判定只依赖
31	// result == nil，不做任何写入/查询类型识别。若实现把带类型的 nil 指针装入
32	// 接口，这里会错误地报告“成功”，测试因此必须失败。
33	func callerResultFailed(r any) bool {
34		return r == nil
35	}
36	
37	// processOK 要求统一入口成功：结果必须是非 nil 接口（错误为 nil），返回结果
38	// 供调用方按具体成功类型（*BatchResult/*QueryResult）使用。
39	func processOK(t *testing.T, store *MetricStore, line string) any {
40		t.Helper()
41		r, lerr := store.ProcessLine(line)
42		if callerResultFailed(r) || lerr != nil {
43			t.Fatalf("ProcessLine(%s): expected non-nil success result and nil error, got r=%v lerr=%+v",
44				line, r, lerr)
45		}
46		return r
47	}
48	
49	// processFail 要求统一入口失败：结果必须是没有动态类型的真正 nil（result == nil
50	// 与反射视角同时成立，直接拦截“带类型 nil 装入接口”的回归），错误必须是非空的
51	// *LineError，带 status 与非空原因文本。返回错误供各测试校验类别细节。
52	func processFail(t *testing.T, store *MetricStore, line string) *LineError {
53		t.Helper()
54		r, lerr := store.ProcessLine(line)
55		if !callerResultFailed(r) {
56			t.Fatalf("ProcessLine(%s): failure must return a true-nil result so result == nil detects it, got %T %+v",
57				line, r, r)
58		}
59		// 接口内不得残留任何动态类型：带类型的 nil 指针同样是回归。
60		if rv := reflect.ValueOf(r); rv.IsValid() {
61			t.Fatalf("ProcessLine(%s): nil result must carry no dynamic type, got %s", line, rv.Type())
62		}
63		if lerr == nil {
64			t.Fatalf("ProcessLine(%s): failure must return a non-nil structured error, got nil", line)
65		}
66		if lerr.Status != "error" {
67			t.Fatalf("ProcessLine(%s): error status = %q, want %q", line, lerr.Status, "error")
68		}
69		if strings.TrimSpace(lerr.Error) == "" {
70			t.Fatalf("ProcessLine(%s): structured error must explain the reason, got empty text", line)
71		}
72		return lerr
73	}
