75	// marshalLineError 把结构化错误序列化为 JSON 字典，便于回归各类错误携带/省略
76	// 哪些字段（index、conflict 必须按类别出现或缺席，而不只是 Go 结构体上为零值）。
77	func marshalLineError(t *testing.T, lerr *LineError) map[string]any {
78		t.Helper()
79		b, err := json.Marshal(lerr)
80		if err != nil {
81			t.Fatalf("marshal LineError: %v", err)
82		}
83		var m map[string]any
84		if err := json.Unmarshal(b, &m); err != nil {
85			t.Fatalf("unmarshal LineError %s: %v", b, err)
86		}
87		if m["status"] != "error" {
88			t.Fatalf("error JSON = %s, want status error", b)
89		}
90		if reason, _ := m["error"].(string); reason == "" {
91			t.Fatalf("error JSON = %s, want a non-empty reason", b)
92		}
93		return m
94	}
