96	// assertNoBatchPositionOrConflict 校验查询失败与整行失败的错误形状：
97	// JSON 中既没有批内位置 index，也没有数值冲突 conflict；入口自身不填行号。
98	func assertNoBatchPositionOrConflict(t *testing.T, m map[string]any, line string) {
99		t.Helper()
100		if _, ok := m["index"]; ok {
101			t.Errorf("ProcessLine(%s): error must not carry batch index, got %v", line, m["index"])
102		}
103		if _, ok := m["conflict"]; ok {
104			t.Errorf("ProcessLine(%s): error must not carry conflict detail, got %v", line, m["conflict"])
105		}
106		if _, ok := m["line"]; ok {
107			t.Errorf("ProcessLine(%s): library entry must not stamp a CLI line number, got %v", line, m["line"])
108		}
109	}
