95			strings.NewReader(`[{"name":"cpu","timestamp":1000,"value":0.5,"labels":{"host":"a"}}]`+"\n"),
96			// 行 2：超长批次（超过上限 1 字节），带合法 JSON 前缀，整行失败。
97			overlongLine(1),
98			strings.NewReader("\n"),
99			// 行 3：后续查询必须照常得到结果，且只能看到行 1 的数据。
100			strings.NewReader(`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`+"\n"),
101		)
